  border-bottom: 1px solid color-mix(in oklch, var(--stroke) 60%, transparent);
}
.nav{
  display:flex; align-items:center; justify-content:space-between;
  gap:14px; padding:14px 0;
}
.brand{
  display:flex; align-items:center; gap:10px;
  font-weight:700; letter-spacing:.2px;
}
.logo{
  width:34px; height:34px; border-radius:12px;
  background: conic-gradient(from 200deg, var(--brand), var(--brand2), var(--brand));
  box-shadow: 0 10px 25px color-mix(in oklch, var(--brand) 25%, transparent);
}
.brand span{font-size:14px}

.navlinks{display:flex; align-items:center; gap:10px; flex-wrap:wrap}
.navlinks a{
  padding:9px 10px; border-radius:12px;
  color:var(--muted);
}
.navlinks a[aria-current="page"]{color:var(--text); background: color-mix(in oklch, var(--surface) 70%, transparent); border:1px solid color-mix(in oklch, var(--stroke) 60%, transparent)}
.navlinks a:hover{color:var(--text); background: color-mix(in oklch, var(--surface) 55%, transparent)}

.actions{display:flex; align-items:center; gap:10px}
.btn{
  border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent);
  background: color-mix(in oklch, var(--surface) 70%, transparent);
  padding:10px 12px; border-radius:12px;
}
.btn:hover{border-color: color-mix(in oklch, var(--brand) 35%, var(--stroke));}
.btn.primary{
  border-color: color-mix(in oklch, var(--brand) 60%, var(--stroke));
  background: linear-gradient(180deg, color-mix(in oklch, var(--brand) 60%, var(--surface)), color-mix(in oklch, var(--brand2) 30%, var(--surface)));
  color: oklch(98% 0.02 270);
}
.btn.ghost{background: transparent}

.pill{display:inline-flex; align-items:center; gap:8px; padding:6px 10px; border-radius:999px; border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent); background: color-mix(in oklch, var(--surface) 70%, transparent); color:var(--muted); font-size:12px}
.badge{font-family:var(--mono); font-size:12px; padding:5px 8px; border-radius:999px; border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent)}
.badge.good{color: color-mix(in oklch, var(--good) 90%, white 10%); border-color: color-mix(in oklch, var(--good) 35%, var(--stroke)); background: color-mix(in oklch, var(--good) 18%, transparent)}
.badge.bad{color: color-mix(in oklch, var(--bad) 90%, white 10%); border-color: color-mix(in oklch, var(--bad) 35%, var(--stroke)); background: color-mix(in oklch, var(--bad) 18%, transparent)}
.badge.neutral{color: var(--muted); background: color-mix(in oklch, var(--surface) 70%, transparent)}

.grid{display:grid; gap:14px}
.card{
  border-radius: var(--radius);
  background: linear-gradient(180deg, color-mix(in oklch, var(--surface) 82%, transparent), color-mix(in oklch, var(--surface2) 78%, transparent));
  border: 1px solid color-mix(in oklch, var(--stroke) 60%, transparent);
  box-shadow: var(--shadow);
}
.card .hd{display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:14px 14px 10px}
.card .hd h2{margin:0; font-size:13px; letter-spacing:.2px; color:var(--text)}
.card .hd p{margin:6px 0 0; font-size:12px; color:var(--muted)}
.card .bd{padding:0 14px 14px}

.hero{
  padding:28px 0 18px;
}
.hero h1{margin:10px 0 8px; font-size:34px; line-height:1.05; letter-spacing:-.6px}
.hero p{margin:0; color:var(--muted); max-width:70ch}
.hero .cta{display:flex; gap:10px; flex-wrap:wrap; margin-top:14px}

.kpi-row{display:flex; flex-wrap:wrap; gap:10px; margin-top:14px}

.tabs{display:flex; gap:8px; flex-wrap:wrap}
.tab{
  padding:8px 10px; border-radius:12px;
  border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent);
  background: transparent;
  color: var(--muted);
  cursor:pointer;
}
.tab[aria-selected="true"]{color:var(--text); background: color-mix(in oklch, var(--surface) 70%, transparent); border-color: color-mix(in oklch, var(--brand) 30%, var(--stroke));}

.table{
  width:100%; border-collapse:separate; border-spacing:0;
  overflow:hidden;
}
.table th, .table td{
  padding:10px 10px;
  border-bottom:1px solid color-mix(in oklch, var(--stroke) 45%, transparent);
  font-size:12px;
}
.table th{color: var(--muted2); font-weight:600; text-align:left; position:sticky; top:0; background: color-mix(in oklch, var(--surface) 65%, transparent)}
.table td{color: var(--text)}
.table tr:hover td{background: color-mix(in oklch, var(--surface2) 55%, transparent)}

.num{font-family: var(--mono); font-variant-numeric: tabular-nums}
.right{text-align:right}
.muted{color:var(--muted)}

.spark{
  width:90px; height:26px; display:block;
  filter: drop-shadow(0 6px 10px color-mix(in oklch, var(--brand) 15%, transparent));
}

.layout-2{
  display:grid;
  grid-template-columns: 1.2fr .8fr;
  gap:14px;
}
.layout-3{
  display:grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap:14px;
}

.footer{padding:26px 0 40px; color:var(--muted); font-size:12px}
.footer .cols{display:grid; grid-template-columns: repeat(6, minmax(0,1fr)); gap:12px}
.footer h4{margin:0 0 8px; font-size:12px; color:var(--text)}
.footer a{display:block; padding:3px 0; color:var(--muted)}
.footer a:hover{color:var(--text)}

/* Chart page */
.terminal{
  height: calc(100vh - 62px);
  display:grid;
  grid-template-columns: 320px 1fr 360px;
  gap:12px;
  padding:12px 0 16px;
}
.panel{border-radius: var(--radius); background: color-mix(in oklch, var(--surface) 80%, transparent); border:1px solid color-mix(in oklch, var(--stroke) 60%, transparent); overflow:hidden}
.panel .phd{padding:12px 12px 10px; border-bottom:1px solid color-mix(in oklch, var(--stroke) 45%, transparent); display:flex; align-items:center; justify-content:space-between; gap:8px}
.panel .phd h3{margin:0; font-size:12px}
.panel .pbd{padding:12px}

.toolbar{
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  padding:10px 0 12px;
}
.toolbar .left{display:flex; align-items:center; gap:8px; flex-wrap:wrap}
.toolbar .tool{
  padding:8px 10px; border-radius:12px;
  border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent);
  background: color-mix(in oklch, var(--surface) 65%, transparent);
  color: var(--muted);
}
.toolbar .tool.active{color:var(--text); border-color: color-mix(in oklch, var(--brand) 35%, var(--stroke));}

.chartbox{height: 520px; border-radius: var(--radius); background: linear-gradient(180deg, color-mix(in oklch, var(--bg2) 80%, transparent), color-mix(in oklch, var(--surface) 60%, transparent)); border:1px solid color-mix(in oklch, var(--stroke) 60%, transparent); position:relative; overflow:hidden}
.chartmeta{position:absolute; top:12px; left:12px; display:flex; gap:8px; align-items:center; flex-wrap:wrap}

.timeframes{display:flex; gap:6px; flex-wrap:wrap}
.tf{padding:7px 8px; border-radius:10px; border:1px solid color-mix(in oklch, var(--stroke) 55%, transparent); background: transparent; color:var(--muted); cursor:pointer; font-size:12px}
.tf[aria-selected="true"]{background: color-mix(in oklch, var(--surface) 70%, transparent); color:var(--text); border-color: color-mix(in oklch, var(--brand) 28%, var(--stroke))}

.watchlist .group{border-top:1px solid color-mix(in oklch, var(--stroke) 45%, transparent)}
.watchlist .group:first-child{border-top:0}
.watchlist .gbtn{width:100%; display:flex; align-items:center; justify-content:space-between; gap:10px; padding:10px 12px; border:0; background:transparent; cursor:pointer; color:var(--text)}
.watchlist .gbtn span{font-size:12px; color:var(--muted)}
.watchlist .items{display:block}
.watchlist .items[hidden]{display:none}
.watchlist table{width:100%; border-collapse:collapse}
.watchlist th, .watchlist td{padding:8px 12px; font-size:12px; border-top:1px solid color-mix(in oklch, var(--stroke) 35%, transparent)}
.watchlist th{color:var(--muted2); font-weight:600; text-align:left}
.watchlist td{color:var(--text)}
.watchlist tr:hover td{background: color-mix(in oklch, var(--surface2) 55%, transparent)}

.kv{display:grid; grid-template-columns: 1fr auto; gap:10px}
.kv .k{color:var(--muted); font-size:12px}
.kv .v{font-family:var(--mono); font-size:12px}

@media (max-width: 1100px){
  .terminal{grid-template-columns: 1fr; height:auto}
  .chartbox{height: 460px}
}
@media (max-width: 720px){
  .hero h1{font-size:28px}
  .footer .cols{grid-template-columns: repeat(2, minmax(0,1fr))}
  .layout-2{grid-template-columns: 1fr}
  .layout-3{grid-template-columns: 1fr}
}
CSS

